#include <dlfcn.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include "../abi/cche.h"
#include "../abi/ccrng.h"
#include "he-symbol-owner.h"
static unsigned tests;
#define CHECK(x) do{tests++;if(!(x)){fprintf(stderr,"line%d %s\n",__LINE__,#x);exit(1);}}while(0)
struct rng{struct ccrng_state r;uint64_t x;};static int gen(struct ccrng_state*r,size_t n,void*out){struct rng*s=(void*)r;for(size_t i=0;i<n;i++){s->x^=s->x<<13;s->x^=s->x>>7;s->x^=s->x<<17;((unsigned char*)out)[i]=s->x;}return 0;}
int main(int argc,char**argv){void*h[2]={dlopen("/usr/lib/system/libcorecrypto.dylib",2),dlopen(argc>1?argv[1]:"/tmp/ecc-he-test.dylib",2)};CHECK(h[0]&&h[1]);finch_test_set_local(h[1],argc>1?argv[1]:"/tmp/ecc-he-test.dylib");size_t(*sz)(unsigned)=dlsym(h[0],"cche_param_ctx_sizeof");int(*init)(void*,unsigned,unsigned)=dlsym(h[1],"cche_param_ctx_init");int(*key)(void*,void*,void*)=dlsym(h[0],"cche_secret_key_generate_from_seed");unsigned char seed[32]={0};for(unsigned provider=0;provider<2;provider++){for(unsigned id=0;id<17;id++){for(unsigned scheme=1;scheme<=2;scheme++){init=dlsym(h[provider],"cche_param_ctx_init");if(id==12)continue;struct he_params*p=calloc(1,sz(id));CHECK(init(p,scheme,id)==0);size_t sn=8+8*(size_t)p->n*p->l;void*sk=calloc(1,sn);CHECK(key(sk,p,seed)==0);for(unsigned gal=0;gal<2;gal++){unsigned elts[2]={3,2*p->n-1};size_t ks[2],wn=0;for(unsigned k=0;k<p->l;k++)wn+=((64-__builtin_clzll(p->q[k]))*(size_t)p->n+7)/8;wn*=((gal?2:1)*(p->l-1));unsigned seedn=32*(gal?2:1)*(p->l-1);void*k[2],*wire[2];unsigned char*seeds[2];for(unsigned i=0;i<2;i++){size_t(*keysz)(void*,unsigned)=dlsym(h[i],gal?"cche_galois_key_sizeof":"cche_relin_key_sizeof");ks[i]=keysz(p,2);k[i]=calloc(1,ks[i]);wire[i]=calloc(1,wn);seeds[i]=calloc(1,seedn);struct rng r={{gen},1234};int rc;if(gal){int(*g)(void*,unsigned,void*,void*,void*,unsigned,void*,void*)=dlsym(h[i],"cche_galois_key_generate");rc=g(k[i],2,elts,sk,p,seedn,seeds[i],&r);}else{int(*g)(void*,void*,void*,unsigned,void*,void*)=dlsym(h[i],"cche_relin_key_generate");rc=g(k[i],sk,p,seedn,seeds[i],&r);}CHECK(rc==0);int(*save)(unsigned,void*,void*)=dlsym(h[i],gal?"cche_galois_key_save":"cche_relin_key_save");CHECK(save(wn,wire[i],k[i])==0);}CHECK(ks[0]==ks[1]);if(memcmp(k[0],k[1],ks[0])){fprintf(stderr,"key mismatch id%u scheme%u gal%u\n",id,scheme,gal);for(size_t j=0;j<ks[0];j++)if(((unsigned char*)k[0])[j]!=((unsigned char*)k[1])[j]){fprintf(stderr,"offset%zu\n",j);break;}return 1;}if(gal){unsigned l=p->l-1;size_t cn=24+2*(8+8*(size_t)p->n*l),pn=8+8*(size_t)p->n;void*c=calloc(1,cn),*pt=calloc(1,pn);uint64_t*v=malloc(p->n*8);for(unsigned j=0;j<p->n;j++)v[j]=j%p->t;int(*encode)(void*,void*,unsigned,void*)=dlsym(h[0],"cche_encode_poly_uint64");CHECK(encode(pt,p,p->n,v)==0);struct rng rng={{gen},333};int(*enc)(void*,void*,void*,void*,unsigned,void*,void*)=dlsym(h[0],"cche_encrypt_symmetric");CHECK(enc(c,pt,p,sk,l,NULL,&rng)==0);void*result[2]={malloc(cn),malloc(cn)};for(unsigned g=0;g<2;g++){for(unsigned a=0;a<2;a++){memcpy(result[a],c,cn);int(*apply)(void*,void*,unsigned,void*)=dlsym(h[a],"cche_ciphertext_apply_galois");CHECK(apply(result[a],c,elts[g],k[a])==0);}if(g==0&&memcmp(result[0],result[1],cn)){fprintf(stderr,"rotation mismatch id%u scheme%u elt%u\n",id,scheme,g);for(size_t j=0;j<cn;j++)if(((unsigned char*)result[0])[j]!=((unsigned char*)result[1])[j]){fprintf(stderr,"offset%zu values %llx/%llx\n",j,(unsigned long long)((uint64_t*)result[0])[j/8],(unsigned long long)((uint64_t*)result[1])[j/8]);break;}return 1;}}/* The host always chooses entry zero. Check the requested entry against the plaintext directly. */
struct he_poly*decoded=calloc(1,pn);int(*decrypt)(void*,void*,void*,void*)=dlsym(h[1],"cche_decrypt");CHECK(decrypt(decoded,p,result[1],sk)==0);for(unsigned jj=0;jj<p->n;jj++){unsigned e=jj*elts[1]%(2*p->n);uint64_t expected=e>=p->n&&v[jj]?p->t-v[jj]:v[jj];if(decoded->data[e%p->n]!=expected)fprintf(stderr,"provider%u id%u scheme%u coeff%u got%llu expected%llu\n",provider,id,scheme,jj,(unsigned long long)decoded->data[e%p->n],(unsigned long long)expected);CHECK(decoded->data[e%p->n]==expected);}free(decoded);free(result[0]);free(result[1]);free(c);free(pt);free(v);}
CHECK(!memcmp(seeds[0],seeds[1],seedn));CHECK(!memcmp(wire[0],wire[1],wn));for(unsigned i=0;i<2;i++){void*loaded=calloc(1,ks[i]);int rc;if(gal){int(*load)(void*,unsigned,void*,void*,unsigned,void*,unsigned,void*)=dlsym(h[i],"cche_galois_key_load");rc=load(loaded,2,elts,p,wn,wire[1-i],seedn,seeds[1-i]);}else{int(*load)(void*,void*,unsigned,void*,unsigned,void*)=dlsym(h[i],"cche_relin_key_load");rc=load(loaded,p,wn,wire[1-i],seedn,seeds[1-i]);}CHECK(rc==0);if(memcmp(k[i],loaded,ks[i])){fprintf(stderr,"load mismatch id%u scheme%u gal%u lib%u\n",id,scheme,gal,i);for(size_t j=0;j<ks[i];j++)if(((unsigned char*)k[i])[j]!=((unsigned char*)loaded)[j]){fprintf(stderr,"offset%zu\n",j);break;}return 1;}free(loaded);}for(unsigned i=0;i<2;i++){free(k[i]);free(wire[i]);free(seeds[i]);}}free(sk);free(p);}}}printf("HE keys and rotation: %u checks passed\n",tests);return 0;}
